const r = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g 'go.mod' -g '*.go' | head -80",workdir:"/app",yield_time_ms:10000,max_output_tokens:2000}),
  tools.exec_command({cmd:"rg -n 'github\\.com/golang/protobuf|google\\.golang\\.org/protobuf|\\*empty\\.Empty|\\*emptypb\\.Empty|timestamp\\.Timestamp|timestamppb\\.Timestamp|empty\\.Empty' --glob '*.go' .",workdir:"/app",yield_time_ms:10000,max_output_tokens:9000})
]); r.forEach((x,i)=>text(JSON.stringify({i,...x})));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"find . -name AGENTS.md -o -name go.mod",workdir:"/app",yield_time_ms:10000,max_output_tokens:2000}),
  tools.exec_command({cmd:"grep -RInE 'github.com/golang/protobuf|google.golang.org/protobuf|\\*empty.Empty|\\*emptypb.Empty|timestamp.Timestamp|timestamppb.Timestamp|empty.Empty' --include='*.go' .",workdir:"/app",yield_time_ms:10000,max_output_tokens:10000}),
  tools.exec_command({cmd:"git status --short && ls -la .codex-role-output",workdir:"/app",yield_time_ms:10000,max_output_tokens:2000})
]); r.forEach((x,i)=>text(JSON.stringify({i,...x})));

